def report(prices):
    total = 0
    for p in prices:
        total += p
    print("Total: $" + format(total, ".2f"))

report([1.5, 2.25])

def total(prices):
    """Return the sum of the prices."""
    return sum(prices)

def format_money(amount):
    """Return the amount as text with a dollar sign and 2 decimals."""
    return "$" + format(amount, ".2f")

def report(prices):
    """Return a one-line report of the total."""
    return "Total: " + format_money(total(prices))

print(report([1.5, 2.25]))

